  (100121, '0a58d077-5d52-4ccb-b4f3-675225c05bb8'::uuid, 'R-(S-HIV-1 OLIGOPEPTIDE-1 TRIPEPTIDE-44 SH-POLYPEPTIDE-100 TRIPEPTIDE-44 SH-POLYPEPTIDE-100 TRIPEPTIDE-44 S-HIV-1 OLIGOPEPTIDE-1)', 'r-(s-HIV-1 Oligopeptide-1 Tripeptide-44 sh-Polypeptide-100 Tripeptide-44 sh-Polypeptide-100 Tripeptide-44 s-HIV-1 Oligopeptide-1)', NULL, NULL, NULL, 'r-(s-HIV-1 Oligopeptide-1 Tripeptide-44 sh-Polypeptide-100 Tripeptide-44 sh-Polypeptide-100 Tripeptide-44 s-HIV-1 Oligopeptide-1) is a single chain fusion peptide, produced by fermentation in  E. coli.  The starting gene is synthesized by the fusion of the genes encoding for s-HIV-1 Oligopeptide-1, Tripeptide-44, and sh-Polypeptide-100. The fusion peptide contains 73 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, 1, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"0a58d077-5d52-4ccb-b4f3-675225c05bb8","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":4.081362,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["r-(s-HIV-1 Oligopeptide-1 Tripeptide-44 sh-Polypeptide-100 Tripeptide-44 sh-Polypeptide-100 Tripeptide-44 s-HIV-1 Oligopeptide-1)"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["r-(s-HIV-1 Oligopeptide-1 Tripeptide-44 sh-Polypeptide-100 Tripeptide-44 sh-Polypeptide-100 Tripeptide-44 s-HIV-1 Oligopeptide-1) is a single chain fusion peptide, produced by fermentation in  E. coli.  The starting gene is synthesized by the fusion of the genes encoding for s-HIV-1 Oligopeptide-1, Tripeptide-44, and sh-Polypeptide-100. The fusion peptide contains 73 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["7E02EDDF49AAC80C125CFF2B675FDA6A"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["R-(S-HIV-1 OLIGOPEPTIDE-1 TRIPEPTIDE-44 SH-POLYPEPTIDE-100 TRIPEPTIDE-44 SH-POLYPEPTIDE-100 TRIPEPTIDE-44 S-HIV-1 OLIGOPEPTIDE-1)"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["100121"],"annexNo":[],"productTypeBodyParts":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["SKIN CONDITIONING - MISCELLANEOUS"],"esDA_IngestDate":["2023-05-23T08:05:30.977+0200"],"currentVersion":["1"],"corporate-search-version":["102"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2023-05-23T08:05:30.934+0200"],"refNo_digit":[],"colour":[],"datasource":["GROWTH_COSING"],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"0a58d077-5d52-4ccb-b4f3-675225c05bb8. Available at: urn:test"}'::jsonb),
  (100124, 'a45a510e-bb01-4163-abe9-a5bbb7328cc6'::uuid, 'SH-OLIGOPEPTIDE-83 SP', 'sh-Oligopeptide-83 SP', NULL, NULL, NULL, 'sh-Oligopeptide-83 SP is a single chain human peptide produced synthetically to be identical to a portion of the protein, Zinc-Alpha-2-Glycoprotein and contains 30 amino acids consisting of alanine, asparagine, aspartic acid, glutamic acid, isoleucine, leucine, lysine, serine, threonine and valine. The parent protein contains a maximum of 298 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, 1, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"a45a510e-bb01-4163-abe9-a5bbb7328cc6","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":3.9631042,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["sh-Oligopeptide-83 SP"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Oligopeptide-83 SP is a single chain human peptide produced synthetically to be identical to a portion of the protein, Zinc-Alpha-2-Glycoprotein and contains 30 amino acids consisting of alanine, asparagine, aspartic acid, glutamic acid, isoleucine, leucine, lysine, serine, threonine and valine. The parent protein contains a maximum of 298 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"referenc