  (100178, '8e4bebf8-e479-46b1-91c1-f877a7c1ffbd'::uuid, 'SH-PENTAPEPTIDE-13 SP', 'sh-Pentapeptide-13 SP', NULL, NULL, NULL, 'sh-Pentapeptide-13 SP is a single chain human peptide produced synthetically to be identical to a portion of the protein, Histone H4, and contains 5 amino acids consisting of glycine, phenylalanine and tyrosine. The parent protein contains a maximum of 103 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, 1, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"8e4bebf8-e479-46b1-91c1-f877a7c1ffbd","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":4.081362,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["sh-Pentapeptide-13 SP"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Pentapeptide-13 SP is a single chain human peptide produced synthetically to be identical to a portion of the protein, Histone H4, and contains 5 amino acids consisting of glycine, phenylalanine and tyrosine. The parent protein contains a maximum of 103 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["92F63DA271B43BB5947E8DBBF0B3F012"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["SH