  (100187, '33b47cc4-8443-44b1-baf6-5667c83554e0'::uuid, 'BIS-HPMA POLY(BUTYLENE/HEXAMETHYLENE CARBONATE)/IPDI COPOLYMER', 'BIS-HPMA POLY(BUTYLENE/HEXAMETHYLENE CARBONATE)/IPDI COPOLYMER', NULL, NULL, NULL, 'Bis-HPMA Poly(Butylene/Hexamethylene Carbonate)/IPDI Copolymer is a urethane polymer formed by a multi-step process. First, a prepolymer is made by reacting 1,4-Butanediol, Hexanediol and Dimethyl Carbonate, which is subsequently reacted with Isophorone Diisocyanate (IPDI). The resulting polymer is end-capped with Hydroxypropyl Methacrylate (HPMA).', NULL, '-', NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, 1, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"33b47cc4-8443-44b1-baf6-5667c83554e0","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":5.0455046,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["BIS-HPMA POLY(BUTYLENE/HEXAMETHYLENE CARBONATE)/IPDI COPOLYMER"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Bis-HPMA Poly(Butylene/Hexamethylene Carbonate)/IPDI Copolymer is a urethane polymer formed by a multi-step process. First, a prepolymer is made by reacting 1,4-Butanediol, Hexanediol and Dimethyl Carbonate, which is subsequently reacted with Isophorone Diisocyanate (IPDI). The resulting polymer is end-capped with Hydroxypropyl Methacrylate (HPMA)."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["69A5A694560E797A11D9D09279E737B3"],"cosmeticRestriction":[],"ecNo":["-"],"maximumConcentration":[],"identifiedIngredient":[],"officia