  (100195, '02851e16-db14-4d0c-a008-85de3cc6388f'::uuid, 'BIS-HPMA POLY(HEXAMETHYLENE/PENTYLENE CARBONATE)/IPDI COPOLYMER', 'BIS-HPMA POLY(HEXAMETHYLENE/PENTYLENE CARBONATE)/IPDI COPOLYMER', NULL, NULL, NULL, 'Bis-HPMA Poly(Hexamethylene/Pentylene Carbonate)/IPDI Copolymer is a urethane polymer formed by a multi-step process. First, a prepolymer is made by condensing Hexanediol, 1,5-Pentanediol, and Dimethyl Carbonate, which is subsequently reacted with Isophorone Diisocyanate (IPDI). The resulting polymer is end-capped with Hydroxypropyl Methacrylate (HPMA).', NULL, '-', NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, 1, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"02851e16-db14-4d0c-a008-85de3cc6388f","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":5.0455046,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["BIS-HPMA POLY(HEXAMETHYLENE/PENTYLENE CARBONATE)/IPDI COPOLYMER"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Bis-HPMA Poly(Hexamethylene/Pentylene Carbonate)/IPDI Copolymer is a urethane polymer formed by a multi-step process. First, a prepolymer is made by condensing Hexanediol, 1,5-Pentanediol, and Dimethyl Carbonate, which is subsequently reacted with Isophorone Diisocyanate (IPDI). The resulting polymer is end-capped with Hydroxypropyl Methacrylate (HPMA)."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["8FF2BD1C4EF35BD9FDA23206BC3B17FC"],"cosmeticRestriction":[],"ecNo":["-"],"maximumConcentration":[],"identifiedIngredient