  (100197, 'ad7e7df8-974d-42e7-9643-1854c0903555'::uuid, 'METHACRYLOYLOXY HYDROXYPROPYL MALTODEXTRIN/ACRYLATES CROSSPOLYMER', 'Methacryloyloxy Hydroxypropyl Maltodextrin/Acrylates Crosspolymer', NULL, NULL, NULL, 'Methacryloyloxy Hydroxypropyl Maltodextrin/Acrylates Crosspolymer is made by a two-step process. First, Maltodextrin is modified by reacting it with Glycidyl Methacrylate. The modified maltodextrin is then polymerized with a mixture of Acrylic Acid, Methacrylic Acid or one of their simple esters, and a crosslinker, Trimethylolpropane Triacrylate.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, 1, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"ad7e7df8-974d-42e7-9643-1854c0903555","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":4.9551744,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["Methacryloyloxy Hydroxypropyl Maltodextrin/Acrylates Crosspolymer"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Methacryloyloxy Hydroxypropyl Maltodextrin/Acrylates Crosspolymer is made by a two-step process. First, Maltodextrin is modified by reacting it with Glycidyl Methacrylate. The modified maltodextrin is then polymerized with a mixture of Acrylic Acid, Methacrylic Acid or one of their simple esters, and a crosslinker, Trimethylolpropane Triacrylate."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["86E186B123FF34396FB5FCF69F221039"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"offi