  (100201, '14750f99-c699-4d49-8f08-d57ef8403f4d'::uuid, 'POLYURETHANE-102', 'Polyurethane-102', NULL, NULL, NULL, 'Polyurethane-102 is a urethane polymer that is made by a multi-step process. First, Di-C12-13 Alkyl Tartrate is transesterified with Bis-Hydroxyethoxypropyl Dimethicone. The mixture of esters is then reacted with a mixture of Isophorone Diisocyanate and 1,6-Hexamethylene Diisocyanate. The resulting polyurethane is capped with Alcohol', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, 1, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"14750f99-c699-4d49-8f08-d57ef8403f4d","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":5.0455046,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["Polyurethane-102"],"otherRestrictions":[],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Polyurethane-102 is a urethane polymer that is made by a multi-step process. First, Di-C12-13 Alkyl Tartrate is transesterified with Bis-Hydroxyethoxypropyl Dimethicone. The mixture of esters is then reacted with a mixture of Isophorone Diisocyanate and 1,6-Hexamethylene Diisocyanate. The resulting polyurethane is capped with Alcohol"],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["61B1BD3141A2528CBC29EE9321DFBA6B"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["POLYURETHANE-102"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["100201"],"annexNo":[],"productTypeBodyParts":[],"phEurN