  (105186, '4403222e-5c5a-49be-b83c-987767cc73cf'::uuid, 'NICOTIANA BENTHAMIANA SH-POLYPEPTIDE-45', 'NICOTIANA BENTHAMIANA SH-POLYPEPTIDE-45', NULL, NULL, NULL, 'Nicotiana Benthamiana sh-Polypeptide-45 is a single chain recombinant human peptide, produced by Nicotiana benthamiana after transformation with either a transient expression system or transgenesis (stable insertion of a copy of a human gene into its DNA). The starting gene is synthesized to be identical to the human gene which codes for Granulocyte Macrophage Colony Stimulating Factor. It contains a maximum of 144 amino acids, which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, 1, NULL, NULL, '{"apiVersion":"2.151","reference":"4403222e-5c5a-49be-b83c-987767cc73cf","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"","summary":"","weight":4.081362,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["NICOTIANA BENTHAMIANA SH-POLYPEPTIDE-45"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Nicotiana Benthamiana sh-Polypeptide-45 is a single chain recombinant human peptide, produced by Nicotiana benthamiana after transformation with either a transient expression system or transgenesis (stable insertion of a copy of a human gene into its DNA). The starting gene is synthesized to be identical to the human gene which codes for Granulocyte Macrophage Colony Stimulating Factor. It contains a maximum of 144 amino acids, which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["4403222e-5c5a-49be-b83c-987767cc73cf"],"reference":["66338847-a9d3-4841-b6b0-72435852937f"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["NICOTIANA BENTHAMIANA SH-POLYPEPTIDE-45"],"officialJournalPublication":["Y"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["105186"],"productTypeBodyParts":[],"annexNo":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["SKIN CONDITIONING - MISCELLANEOUS"],"esDA_IngestDate":["2024-08-26T11:15:08.516+0200"],"currentVersion":["1"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2024-08-26T11:15:08.504+0200"],"refNo_digit":[],"colour":[],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"4403222e-5c5a-49be-b83c-987767cc73cf. Available at: urn:test"}'::jsonb),
  (105187, 'cfc1daa3-4dff-4068-8527-ac083a2663cf'::uuid, 'NICOTIANA BENTHAMIANA SH-POLYPEPTIDE-7', 'Nicotiana Benthamiana sh-Polypeptide-7', NULL, NULL, NULL, 'Nicotiana Benthamiana sh-Polypeptide-7 is a single chain recombinant human peptide, produced by Nicotiana benthamiana after transformation with either a transient expression system or transgenesis (stable insertion of a copy of a human gene into its DNA). The starting gene is synthesized to be identical to the human gene which codes for Somatotropin. It contains a maximum of 217 amino acids, which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, 1, NULL, NULL, '{"apiVersion":"2.151","reference":"cfc1daa3-4dff-4068-8527-ac083a2663cf","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"","summary":"","weight":4.081362,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["Nicotiana Benthamiana sh-Polypeptide-7"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Nicotiana Benthamiana sh-Polypeptide-7 is a single chain recombinant human peptide, produced by Nicotiana benthamiana after transformation with either a transient expression system or transgenesis (stable insertion of a copy of a human gene into its DNA). The starting gene is synthesized to be identical to the human gene which codes for Somatotropin. It contains a maximum of 217 amino acids, which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA49599