  (105251, '5d135157-53d1-4b9b-a951-1763abbe4262'::uuid, 'RH-OLIGOPEPTIDE-1 SR-BOVINE POLYPEPTIDE-1 RH-POLYPEPTIDE-84', 'RH-OLIGOPEPTIDE-1 SR-BOVINE POLYPEPTIDE-1 RH-POLYPEPTIDE-84', NULL, NULL, NULL, 'rh-Oligopeptide-1 sr-Bovine Polypeptide-1 rh-Polypeptide-84 is a single chain fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from rh-Oligopeptide-1, sr-Bovine Polypeptide-1 and rh-Polypeptide-84. The fusion peptide consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, 1, NULL, NULL, '{"apiVersion":"2.151","reference":"5d135157-53d1-4b9b-a951-1763abbe4262","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"","summary":"","weight":4.081362,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["RH-OLIGOPEPTIDE-1 SR-BOVINE POLYPEPTIDE-1 RH-POLYPEPTIDE-84"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["rh-Oligopeptide-1 sr-Bovine Polypeptide-1 rh-Polypeptide-84 is a single chain fusion peptide, produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the gene from rh-Oligopeptide-1, sr-Bovine Polypeptide-1 and rh-Polypeptide-84. The fusion peptide consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["5d135157-53d1-4b9b-a951-1763abbe4262"],"reference":["2c40b709-39c3-41bb-bd13-81ba69e86867"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["RH-OLIGOPEPTIDE-1 SR-BOVINE POLYPEPTIDE-1 RH-POLYPEPTIDE-84"],"officialJournalP