  (105260, '170fb89e-6737-4489-8337-72d94f8e46cd'::uuid, 'SEA CUCUMBER SECRETION EXTRACT', 'SEA CUCUMBER SECRETION EXTRACT', NULL, NULL, NULL, 'Sea Cucumber Secretion Extract is the extract of the secretion obtained from the sea cucumber, Apostichopus japonicus, Cucumaria japonica, and/or Stichopus japonicus.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, 1, NULL, NULL, '{"apiVersion":"2.151","reference":"170fb89e-6737-4489-8337-72d94f8e46cd","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"","summary":"","weight":6.070189,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SEA CUCUMBER SECRETION EXTRACT"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Sea Cucumber Secretion Extract is the extract of the secretion obtained from the sea cucumber, Apostichopus japonicus, Cucumaria japonica, and/or Stichopus japonicus."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["170fb89e-6737-4489-8337-72d94f8e46cd"],"reference":["31eae34a-4359-49be-983a-cea2bb080f65"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["SEA CUCUMBER SECRETION EXTRACT"],"officialJournalPublication":["Y"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["105260"],"productTypeBodyParts":[],"annexNo":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["ASTRINGENT","BLEACHING","SKIN PROTECTING","EXFOLIATING","SKIN CONDITIONING - MISCELLANEOUS"],"esDA_IngestDate":["2024-08-26T14:49:16.828+0200"],"currentVersion":["1"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":