  (105262, 'ac92df1a-a113-440d-a98f-060fdc6a6d9c'::uuid, 'SHEEP FIBROBLAST CONDITIONED MEDIA', 'SHEEP FIBROBLAST CONDITIONED MEDIA', NULL, NULL, NULL, 'Sheep Fibroblast Conditioned Media is the growth media removed from cultures of fibroblasts isolated from sheep after several days of growth. The starting media is Dulbecco''s Modified Eagle Medium, and may or may not contain fetal bovine serum.', NULL, NULL, 'Please consider whether entry 419 of Annex II to the Cosmetics Regulation 1223/2009 is applicable. According to entry 419, category 1 material and Category 2 material as defined in Articles 4 and 5 respectively of Regulation (EC) No 1774/2002, and ingredients derived therefrom are prohibited in cosmetics products. Regulation (EC) No 1774/2002 has been repealed and replaced by Regulation No. 1069/2009. For Category 1 and 2 materials in Regulation No. 1069/2009, please see Article 8 and 9, respectively.', '[]', NULL, NULL, 'Active', FALSE, TRUE, 1, NULL, NULL, '{"apiVersion":"2.151","reference":"ac92df1a-a113-440d-a98f-060fdc6a6d9c","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"","summary":"","weight":7.7267504,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SHEEP FIBROBLAST CONDITIONED MEDIA"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Sheep Fibroblast Conditioned Media is the growth media removed from cultures of fibroblasts isolated from sheep after several days of growth. The starting media is Dulbecco''s Modified Eagle Medium, and may or may not contain fetal bovine serum."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["ac92df1a-a113-440d-a98f-060fdc6a6d9c"],"reference":["2cc433ad-c99a-41bc-848d-4527a09e57b8"],"cosmeticRestriction":["Please consider whether entry 419 of Annex II to the Cosmetics Regulation 1223/2009 is applicable. According to entry 419, category 1 material and Category 2 material as defined in Articles 4 and 5 respectively of Regulation (EC) No 1774/2002, and ingredients derived therefrom are prohibited in cosmetics products. Regulation (EC) No 1774/2002 has been repealed and replaced by Regulation No. 1069/2009. For Category 1 and 2 materials in Regulation No. 1069/2009, please see Article 8 and 9, respectively."],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["SHEEP FIBROBLAST CONDITIONED MEDIA"],"officialJournalPublication":["Y"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["105262"],"productTypeBodyParts":[],"annexNo":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["ANTI-SEBORRHEIC","SKIN CONDITIONING - HUMECTANT"],"esDA_IngestDate":["2024-08-26T14:52:21.258+0200"],"currentVersion":["1"],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2024-08-26T14:52:21.246+0200"],"refNo_digit":[],"colour":[],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"ac92df1a-a113-440d-a98f-060fdc6a6d9c. Available at: urn:test"}'::jsonb),
  (105263, '69fc5860-48e5-4e3b-a90d-f546703c6ab8'::uuid, 'SH-PENTAPEPTIDE-6 TRIFLUOROACETATE', 'SH-PENTAPEPTIDE-6 TRIFLUOROACETATE', NULL, NULL, NULL, 'sh-Pentapeptide-6 Trifluoroacetate is the trifluoroacetate salt of a single chain human peptide, produced synthetically to be identical to a portion of multiple forms of collagen. sh-Pentapeptide-6 Trifluoroacetate contains 5 amino acids consisting of alanine, glycine, and proline.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, 1, NULL, NULL, '{"apiVersion":"2.151","reference":"69fc5860-48e5-4e3b-a90d-f546703c6ab8","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"","summary":"","weight":4.081362,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["SH-PENTAPEPTIDE-6 TRIFLUOROACETATE"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Pentapeptide-6 Trifluoroacetate is the trifluoroacetate salt of a single chain human peptide, produced synthetically to be identical to a portion of multiple forms of collagen. sh-Pentapeptide-6 Trifluoroacetate contains 5 amino acids consisting of alanine, glycine, and proline."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["69fc5860-48e5-4e3b-a90d-f546703c6ab8"],"reference":["16efa840-ed6a-45d6-8feb-68b9875287d8"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["SH-PENTAPEPTIDE-6 TRIFLUOROACETATE"],"officialJournalPublication":["Y"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["105263"],"productTypeBodyParts":[],"annexNo":[],"phEurName":[],"es_ContentType":["text/plain"],"otherRegulations":[],"classificationInformation":["[