  (106126, '2769e5a9-9278-444c-954f-2f349b3ce782'::uuid, 'SR-MUSSEL POLYPEPTIDE-5', 'sr-Mussel Polypeptide-5', NULL, NULL, NULL, 'sr-Mussel Polypeptide-5 is a single chain recombinant mussel peptide, produced by fermentation in Pichia. The starting gene is synthesized to be identical to the gene which codes for Adhesive Plaque Matrix Protein derived from mussel. The parent protein contains a maximum of 565 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"2769e5a9-9278-444c-954f-2f349b3ce782","url":"urn:test","contentType":"application/octet-stream","language":"en","databaseLabel":"","summary":"","weight":6.861625,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["sr-Mussel Polypeptide-5"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sr-Mussel Polypeptide-5 is a single chain recombinant mussel peptide, produced by fermentation in Pichia. The starting gene is synthesized to be identical to the gene which codes for Adhesive Plaque Matrix Protein derived from mussel. The parent protein contains a maximum of 565 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["2769e5a9-9278-444c-954f-2f349b3ce782"],"reference":["f4eacfc0-7525-4b6f-8f9a-8f09d23dc5f1"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["SR-MUSSEL POLYPEPTIDE-5"],