  (106132, 'b7a4e931-107a-483c-9368-2290b643d581'::uuid, 'COCO/OLIVAMIDOPROPYL BETAINE', 'Coco/Olivamidopropyl Betaine', NULL, NULL, NULL, 'Coco/Olivamidopropyl Betaine is the zwitterion (inner salt) that conforms generally to the formula, where RCO- represents a blend of fatty acids derived from coconut oil and olive oil.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"b7a4e931-107a-483c-9368-2290b643d581","url":"urn:test","contentType":"application/octet-stream","language":"en","databaseLabel":"","summary":"","weight":3.711493,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["Coco/Olivamidopropyl Betaine"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Coco/Olivamidopropyl Betaine is the zwitterion (inner salt) that conforms generally to the formula, where RCO- represents a blend of fatty acids derived from coconut oil and olive oil."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["b7a4e931-107a-483c-9368-2290b643d581"],"reference":["e580e368-9c71-480e-b0a0-c4b4938836c5"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["COCO/OLIVAMIDOPROPYL BETAINE"],"officialJournalPublication":["Y"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["106132"],"productTypeBodyParts":[],"annexNo":[],"phEurName":[],"es_ContentType":["application/octet-stream"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["SKIN CONDITIONING - EMOLLIENT","HAIR CONDITIONING","SURFACTANT - CLEANSING"],"esDA_FirstIngestDate":["2026-05-26T13:54:43.913+0200"],"esDA_IngestDate":["2026-05-26T13:5