  (106133, '1d5e77d1-a7a9-4e58-aa7a-1efa7b6efc05'::uuid, 'AMINOPROPYL ALUMINUM POLYSILSESQUIOXANE', 'Aminopropyl Aluminum Polysilsesquioxane', NULL, NULL, NULL, 'Aminopropyl Aluminum Polysilsesquioxane is a resinous material composed of a mixture of three-dimensional siloxane polymers and oligomers with cage structures. Aminopropyl Aluminum Polysilsesquioxane Chloride is prepared by the hydrolysis and condensation of 3-aminopropyltriethoxysilane, and reaction with aluminum chloride.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"1d5e77d1-a7a9-4e58-aa7a-1efa7b6efc05","url":"urn:test","contentType":"application/octet-stream","language":"en","databaseLabel":"","summary":"","weight":5.236234,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["Aminopropyl Aluminum Polysilsesquioxane"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Aminopropyl Aluminum Polysilsesquioxane is a resinous material composed of a mixture of three-dimensional siloxane polymers and oligomers with cage structures. Aminopropyl Aluminum Polysilsesquioxane Chloride is prepared by the hydrolysis and condensation of 3-aminopropyltriethoxysilane, and reaction with aluminum chloride."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["1d5e77d1-a7a9-4e58-aa7a-1efa7b6efc05"],"reference":["28db4dd5-0590-422c-9608-31f2679af6e2"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["AMINOPROPYL ALUMINUM POLYSILSESQUIOXANE"],"officialJournalPublication":["Y"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["106133"],"productTypeBody