  (106136, 'b089620a-772f-4ae9-bf4c-ce04997ddf76'::uuid, 'SACCHAROMYCES/MADHUCA LONGIFOLIA FLOWER FERMENT FILTRATE', 'Saccharomyces/Madhuca Longifolia Flower Ferment Filtrate', NULL, NULL, NULL, 'Saccharomyces/Madhuca Longifolia Flower Ferment Filtrate is a filtrate of the product obtained by the fermentation of the flowers of Madhuca longifolia by the microorganism, Saccharomyces.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"b089620a-772f-4ae9-bf4c-ce04997ddf76","url":"urn:test","contentType":"application/octet-stream","language":"en","databaseLabel":"","summary":"","weight":3.9449465,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["Saccharomyces/Madhuca Longifolia Flower Ferment Filtrate"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Saccharomyces/Madhuca Longifolia Flower Ferment Filtrate is a filtrate of the product obtained by the fermentation of the flowers of Madhuca longifolia by the microorganism, Saccharomyces."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["b089620a-772f-4ae9-bf4c-ce04997ddf76"],"reference":["7840f634-2ada-4913-a9de-548a07ba5e23"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["SACCHAROMYCES/MADHUCA LONGIFOLIA FLOWER FERMENT FILTRATE"],"officialJournalPublication":["Y"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["106136"],"productTypeBodyParts":[],"annexNo":[],"phEurName":[],"es_ContentType":["application/octet-stream"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["ANTIOXIDANT","SKIN PROTECTING","SKIN CONDITIONI