  (106137, '384fec50-73db-462b-b7e0-999831907a81'::uuid, 'RETINOYL PEG-2 HEXAPEPTIDE-8 AMIDE HCL', 'Retinoyl PEG-2 Hexapeptide-8 Amide HCl', NULL, NULL, NULL, 'Retinoyl PEG-2 Hexapeptide-8 Amide HCl is the hydrochloride salt of the product obtained by the reaction of Retinoic Acid, two units of polyethylene glycol and Hexapeptide-8 in which the C-terminus is an amide.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"384fec50-73db-462b-b7e0-999831907a81","url":"urn:test","contentType":"application/octet-stream","language":"en","databaseLabel":"","summary":"","weight":3.9449465,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["Retinoyl PEG-2 Hexapeptide-8 Amide HCl"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Retinoyl PEG-2 Hexapeptide-8 Amide HCl is the hydrochloride salt of the product obtained by the reaction of Retinoic Acid, two units of polyethylene glycol and Hexapeptide-8 in which the C-terminus is an amide."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["384fec50-73db-462b-b7e0-999831907a81"],"reference":["14755c17-9852-4d36-b05a-bbbf1f249cfc"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["RETINOYL PEG-2 HEXAPEPTIDE-8 AMIDE HCL"],"officialJournalPublication":["Y"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["106137"],"productTypeBodyParts":[],"annexNo":[],"phEurName":[],"es_ContentType":["application/octet-stream"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["ANTIOXIDANT","SKIN CONDITIONING - EMOLLIENT","SKIN PROTECTING","SKIN CONDIT