  (106138, '8ba7ffcf-aaeb-41f4-b4a0-0ab25317aa0a'::uuid, 'HUMAN DECIDUOUS TOOTH PULP STEM CELL CONDITIONED MEDIA', 'Human Deciduous Tooth Pulp Stem Cell Conditioned Media', NULL, NULL, NULL, 'Human Deciduous Tooth Pulp Stem Cell Conditioned Media is the growth media removed from cultures of human deciduous tooth pulp stem cells after several days of growth. The starting media is Dulbecco''s Modified Eagle Medium, and may or may not contain fetal bovine serum.', NULL, NULL, 'II/416', '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"8ba7ffcf-aaeb-41f4-b4a0-0ab25317aa0a","url":"urn:test","contentType":"application/octet-stream","language":"en","databaseLabel":"","summary":"","weight":3.7249496,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["Human Deciduous Tooth Pulp Stem Cell Conditioned Media"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Human Deciduous Tooth Pulp Stem Cell Conditioned Media is the growth media removed from cultures of human deciduous tooth pulp stem cells after several days of growth. The starting media is Dulbecco''s Modified Eagle Medium, and may or may not contain fetal bovine serum."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["8ba7ffcf-aaeb-41f4-b4a0-0ab25317aa0a"],"reference":["0c991f56-6972-4ef8-8c7c-902645822323"],"cosmeticRestriction":["II/416"],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["HUMAN DECIDUOUS TOOTH PULP STEM CELL CONDITIONED MEDIA"],"officialJournalPublication":["Y"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["106138"],"productTypeBodyParts":[],"annexNo":[],"phEurName":