  (106141, '6729b911-6c6c-48e3-96df-59d3fb2c09b5'::uuid, 'JAPANESE QUAIL FIBROBLAST CELL CONDITIONED MEDIUM', 'Japanese Quail Fibroblast Cell Conditioned Medium', NULL, NULL, NULL, 'Japanese Quail Fibroblast Cell Conditioned Medium is the growth media removed from cultures of Japanese quail fibroblast cells after several days of growth. The starting media is Dulbecco''s Modified Eagle Medium, and may or may not contain fetal bovine serum.', NULL, NULL, 'Please consider whether entry 419 of Annex II to the Cosmetics Regulation 1223/2009 is applicable. According to entry 419, category 1 material and Category 2 material as defined in Articles 4 and 5 respectively of Regulation (EC) No 1774/2002, and ingredients derived therefrom are prohibited in cosmetics products. Regulation (EC) No 1774/2002 has been repealed and replaced by Regulation No. 1069/2009. For Category 1 and 2 materials in Regulation No. 1069/2009, please see Article 8 and 9, respectively.', '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"6729b911-6c6c-48e3-96df-59d3fb2c09b5","url":"urn:test","contentType":"application/octet-stream","language":"en","databaseLabel":"","summary":"","weight":4.081362,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["Japanese Quail Fibroblast Cell Conditioned Medium"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Japanese Quail Fibroblast Cell Conditioned Medium is the growth media removed from cultures of Japanese quail fibroblast cells after several days of growth. The starting media is Dulbecco''s Modified Eagle Medium, and may or may not contain fetal bovine serum."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB924