  (106142, 'ce225fae-fa25-408e-aac0-2831852f2d35'::uuid, 'SR-COW POLYPEPTIDE-5', 'sr-Cow Polypeptide-5', NULL, NULL, NULL, 'sr-Cow Polypeptide-5 is a single chain recombinant protein produced by fermentation in E. coli. The starting gene is synthetically produced to be identical to a portion of the gene which codes for Insulin-Like Growth Factor 1, which is found in the cow, Bos taurus. The protein contains a maximum of 154 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"ce225fae-fa25-408e-aac0-2831852f2d35","url":"urn:test","contentType":"application/octet-stream","language":"en","databaseLabel":"","summary":"","weight":4.081362,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["sr-Cow Polypeptide-5"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sr-Cow Polypeptide-5 is a single chain recombinant protein produced by fermentation in E. coli. The starting gene is synthetically produced to be identical to a portion of the gene which codes for Insulin-Like Growth Factor 1, which is found in the cow, Bos taurus. The protein contains a maximum of 154 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["ce225fae-fa25-408e-aac0-2831852f2d35"],"reference":["d9343c88-d2e3-4617-a83d-53a8137e71fd"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["SR-COW POLYPEPTIDE-5"],"officialJournalPublication":["Y"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["106142"],"productTypeBodyParts":[],"annexNo":[],"phEurName":[],"es_ContentType":["application/octet-stream"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["SKIN CONDITIONING - MISCELLANEOUS"],"esDA_FirstIngestDate":["2026-06-25T15:09:20.266+0200"],"esDA_IngestDate":["2026-06-25T15:09:20.266+0200"],"currentVersion":[],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2026-06-25T15:09:20.247+0200"],"refNo_digit":[],"colour":[],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"ce225fae-fa25-408e-aac0-2831852f2d35. Available at: urn:test"}'::jsonb),
  (106143, 'ad9379ee-c61e-42bb-bcfe-cf0963f9c772'::uuid, 'BARLEY SR-(PIG POLYPEPTIDE-3 HEXAPEPTIDE-40)', 'Barley sr-(Pig Polypeptide-3 Hexapeptide-40)', NULL, NULL, NULL, 'Barley sr-(Pig Polypeptide-3 Hexapeptide-40) is a single chain recombinant peptide produced by Hordeum vulgare after transformation with either a transient expression system or transgenesis (stable insertion of a copy of the synthetic gene into its DNA). The starting gene is synthesized by the fusion of the genes from sr-Pig Polypeptide-3 and Hexapeptide-40. The peptide contains 58 amino acids which may contain disulfide bonds and/or glycosylation. The fusion peptide consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"ad9379ee-c61e-42bb-bcfe-cf0963f9c772","url":"urn:test","contentType":"application/octet-stream","language":"en","databaseLabel":"","summary":"","weight":4.081362,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["Barley sr-(Pig Polypeptide-3 Hexapeptide-40)"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Barley sr-(Pig Polypeptide-3 Hexapeptide-40) is a single chain recombinant peptide produced by Hordeum vulgare after transformation with either a transient expression system or transgenesis (stable insertion of a copy of the synthetic gene into its DNA). The starting gene is synthesized by the fusion of the genes from sr-Pig Polypeptide-3 and Hexapeptide-40. The peptide contains 58 amino acids which may contain disulfide bonds and/or glycosylation. The fusion peptide consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["ad9379ee-c61e-42bb-bcfe-cf0963f9c772"],"reference":["9eee9ab7-6ab9-42f5-9bf7-4f3334125916"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["BARLEY SR-(PIG POLYPEPTIDE-3 HEXAPEPTIDE-40)"],"officialJournalPublication":["Y"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["106143"],"productTypeBodyParts":[],"annexNo":[],"phEurName":[],"es_ContentType":["application/octet-stream"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["SKIN CONDITIONING - MISCELLANEOUS"],"esDA_FirstIngestDate":["2026-06-08T14:24:15.586+0200"],"esDA_IngestDate":["2026-06-08T14:24:15.586+0200"],"currentVersion":[],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2026-06-08T14:24:15.564+0200"],"refNo_digit":[],"colour":[],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"ad9379ee-c61e-42bb-bcfe-cf0963f9c772. Available at: urn:test"}'::jsonb),
  (106144, '69fbc503-3e0d-49b2-a2d7-64915a436c27'::uuid, 'SR-MUSSEL OLIGOPEPTIDE-4', 'sr-Mussel Oligopeptide-4', NULL, NULL, NULL, 'sr-Mussel Oligopeptide-4 is a single chain recombinant protein produced by fermentation in E. coli. The starting gene is synthesized to be identical to the gene which codes for Foot Protein-5 found in the mussel, Mytilus californianus. The parent protein contains a maximum of 96 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"69fbc503-3e0d-49b2-a2d7-64915a436c27","url":"urn:test","contentType":"application/octet-stream","language":"en","databaseLabel":"","summary":"","weight":3.9449465,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["sr-Mussel Oligopeptide-4"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sr-Mussel Oligopeptide-4 is a single chain recombinant protein produced by fermentation in E. coli. The starting gene is synthesized to be identical to the gene which codes for Foot Protein-5 found in the mussel, Mytilus californianus. The parent protein contains a maximum of 96 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["69fbc503-3e0d-49b2-a2d7-64915a436c27"],"reference":["cc06f054-7de0-4732-8c46-1ffdf3532bd1"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["SR-MUSSEL OLIGOPEPTIDE