  (106200, '364f4f5f-2f9c-425e-bad0-23ee5a4856a7'::uuid, 'CENTELLA ASIATICA SH-OLIGOPEPTIDE-1', 'Centella Asiatica sh-Oligopeptide-1', NULL, NULL, NULL, 'Centella Asiatica sh-Oligopeptide-1 is a single chain recombinant human peptide, produced by Centella asiatica, after transformation with either a transient expression system or transgenesis (stable insertion of a copy of a human gene into its DNA). The starting gene is synthesized to be identical to the human gene which codes for Epidermal Growth Factor. It contains a maximum of 53 amino acids, which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"364f4f5f-2f9c-425e-bad0-23ee5a4856a7","url":"urn:test","contentType":"application/octet-stream","language":"en","databaseLabel":"","summary":"","weight":5.236234,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["Centella Asiatica sh-Oligopeptide-1"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Centella Asiatica sh-Oligopeptide-1 is a single chain recombinant human peptide, produced by Centella asiatica, after transformation with either a transient expression system or transgenesis (stable insertion of a copy of a human gene into its DNA). The starting gene is synthesized to be identical to the human gene which codes for Epidermal Growth Factor. It contains a maximum of 53 amino acids, which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["364f4f5f-2f9c-425e-bad0-23ee5a4856a7"],"reference":["ddaf3931-5c0c-4c4e-9f22-5ba1a4fb83d0"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["CENTELLA ASIATICA SH-OLIGOPEPTIDE-1"],"officialJournalPublication":["Y"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["106200"],"productTypeBodyParts":[],"annexNo":[],"phEurName":[],"es_ContentType":["application/octet-stream"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["ANTIMICROBIAL","ANTIOXIDANT","HAIR CONDITIONING","SKIN CONDITIONING - HUMECTANT","SKIN CONDITIONING - MISCELLANEOUS"],"esDA_FirstIngestDate":["2026-06-08T14:27:33.182+0200"],"esDA_IngestDate":["2026-06-08T14:27:33.182+0200"],"currentVersion":[],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2026-06-08T14:27:33.163+0200"],"refNo_digit":[],"colour":[],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"364f4f5f-2f9c-425e-bad0-23ee5a4856a7. Available at: urn:test"}'::jsonb),
