  (106210, '7c28621b-290f-4487-a87b-8e36ca10c116'::uuid, '(COPPER TRIPEPTIDE-1/OLIGOPEPTIDE-295/ZINC OLIGOPEPTIDE-296) PEPTIDES', '(Copper Tripeptide-1/Oligopeptide-295/Zinc Oligopeptide-296) Peptides', NULL, NULL, NULL, '(Copper Tripeptide-1/Oligopeptide-295/Zinc Oligopeptide-296) Peptides are the random peptides created during solid-phase synthesis of Copper Tripeptide-1, Oligopeptide-295, and Zinc Oligopeptide-296.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"7c28621b-290f-4487-a87b-8e36ca10c116","url":"urn:test","contentType":"application/octet-stream","language":"en","databaseLabel":"","summary":"","weight":5.236234,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["(Copper Tripeptide-1/Oligopeptide-295/Zinc Oligopeptide-296) Peptides"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["(Copper Tripeptide-1/Oligopeptide-295/Zinc Oligopeptide-296) Peptides are the random peptides created during solid-phase synthesis of Copper Tripeptide-1, Oligopeptide-295, and Zinc Oligopeptide-296."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["7c28621b-290f-4487-a87b-8e36ca10c116"],"reference":["ca94b0ca-700b-46dc-af66-c38551736180"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["(COPPER TRIPEPTIDE-1/OLIGOPEPTIDE-295/ZINC OLIGOPEPTIDE-296) PEPTIDES"],"officialJournalPublication":["Y"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["106210"],"productTypeBodyParts":[],"annexNo":[],"phEurName":[],"es_ContentType":["application/octet-stream"],"otherRegulations":[],"classificationInformation