  (106211, 'dc57c99b-2272-476e-9d7e-682d83948c7f'::uuid, 'S-HONEY BEE OLIGOPEPTIDE-1', 's-Honey Bee Oligopeptide-1', NULL, NULL, NULL, 's-Honey Bee Oligopeptide-1 is a single chain protein fragment synthetically produced based on a sequence from Melittin which is found in the honey bee, Apis, that contains 26 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"dc57c99b-2272-476e-9d7e-682d83948c7f","url":"urn:test","contentType":"application/octet-stream","language":"en","databaseLabel":"","summary":"","weight":3.7249496,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["s-Honey Bee Oligopeptide-1"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["s-Honey Bee Oligopeptide-1 is a single chain protein fragment synthetically produced based on a sequence from Melittin which is found in the honey bee, Apis, that contains 26 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["dc57c99b-2272-476e-9d7e-682d83948c7f"],"reference":["007ceb78-4100-40cd-9449-54c7362132dd"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["S-HONEY BEE OLIGOPEPTIDE-1"],"officialJournalPublication":["Y"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["106211"],"productTypeBodyParts":[],"annexNo":[],"phEurName":[],"es_ContentType":["application/octet-stream