  (106212, 'f27ee96d-4a01-4db5-ba81-59ae989dd9c6'::uuid, 'OLIGOPEPTIDE-300 DI (D-HEPTAPEPTIDE-72)', 'Oligopeptide-300 Di (D-Heptapeptide-72)', NULL, NULL, NULL, 'Oligopeptide-300 Di (D-Heptapeptide-72) is the synthetic peptide consisting of Oligopeptide-300 and two repeats of D-Heptapeptide-72.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"f27ee96d-4a01-4db5-ba81-59ae989dd9c6","url":"urn:test","contentType":"application/octet-stream","language":"en","databaseLabel":"","summary":"","weight":4.081362,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["Oligopeptide-300 Di (D-Heptapeptide-72)"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Oligopeptide-300 Di (D-Heptapeptide-72) is the synthetic peptide consisting of Oligopeptide-300 and two repeats of D-Heptapeptide-72."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["f27ee96d-4a01-4db5-ba81-59ae989dd9c6"],"reference":["ce955a12-9232-4dd7-91cb-2582b5be0be0"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["OLIGOPEPTIDE-300 DI (D-HEPTAPEPTIDE-72)"],"officialJournalPublication":["Y"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["106212"],"productTypeBodyParts":[],"annexNo":[],"phEurName":[],"es_ContentType":["application/octet-stream"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["SKIN CONDITIONING - MISCELLANEOUS"],"esDA_FirstIngestDate":["2026-06-18T14:41:47.177+0200"],"esDA_IngestDate":["2026-06-18T14:41:47.177+0200"],"currentVersion":[],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2