  (106213, '84918669-440c-400e-83dd-2f292faa9033'::uuid, 'POLYURETHANE-111', 'Polyurethane-111', NULL, NULL, NULL, 'Polyurethane-111 is complex urethane polymer that is formed by interfacial polymerization to produce a polymer shell for the purpose of encapsulating a water-insoluble oil. The process starts by dispersing Sorbitol Polyglycidyl Ether, Polyhexamethylene Diisocyanate, and Polymethylene Polyphenylisocyanate into the oil that is to be encapsulated. Separately, a water phase is prepared by dispersing Zea Mays Starch, Acacia Senegal Gum, Ceratonia Siliqua Gum, Sodium Silicate, and Trimethoxysilylpropyl Diethylentriamine in water. The oil phase with the isocyanates is dispersed in the water phase and mixed to produce the desired droplet size. The dispersion is heated to initiate polymerization. Finally, a separate mixture of Tetraethyl Orthosilicate and PPG-7 in water are added to the dispersion of encapsulated water-insoluble oil.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"84918669-440c-400e-83dd-2f292faa9033","url":"urn:test","contentType":"application/octet-stream","language":"en","databaseLabel":"","summary":"","weight":5.812675,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["Polyurethane-111"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Polyurethane-111 is complex urethane polymer that is formed by interfacial polymerization to produce a polymer shell for the purpose of encapsulating a water-insoluble oil. The process starts by dispersing Sorbitol Polyglycidyl Ether, Polyhexamethylene Diisocyanate, and Polymethylene Polyphenylisocyanate into the oil that is to be encapsulated. Separately, a water phase is prepared by dispersing Zea Mays Starch, Acacia Senegal Gum, Ceratonia Siliqua Gum, Sodium Silicate, and Trimethoxysilylpropyl Diethylentriamine in water. The oil phase with the isocyanates is dispersed in the water phase and mixed to produce the desired droplet size. The dispersion is heated to initiate polymerization. Finally, a separate mixture of Tetraethyl Orthosilicate and PPG-7 in water are added to the dispersion of encapsulated water-insoluble oil."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["84918669-440c-400e-83dd-2f292faa9033"],"reference":["2a42b181-8cf4-49e3-a213-54ececf90203"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["POLYURETHANE-111"],"officialJournalPublication":["Y"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["106213"],"productTypeBodyParts":[],"annexNo":[],"phEurName":[],"es_ContentType":["application/octet-stream"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["EMULSION STABILISING","FILM FORMING"],"esDA_FirstIngestDate":["2026-06-23T14:19:45.849+0200"],"esDA_IngestDate":["2026-06-23T14:19:45.849+0200"],"currentVersion":[],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2026-06-23T14:19:45.831+0200"],"refNo_digit":[],"colour":[],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"84918669-440c-400e-83dd-2f292faa9033. Available at: urn:test"}'::jsonb),
  (106214, 'e3b4feb2-2d6a-42f4-b2b1-53de2d9a428e'::uuid, 'S-GRAHAM’S FROG OLIGOPEPTIDE-1', 's-Graham’s Frog Oligopeptide-1', NULL, NULL, NULL, 's-Graham’s Frog Oligopeptide-1 is a single chain peptide produced synthetically to be identical to a portion of the protein Immunoregulatory Peptide Odorregulin E1 which is found in the frog, Rana draytonii, and contains 11 amino acids which may contain disulfide bonds and/or glycosylation. The parent protein contains a maximum of 53 amino acids and consists of the proper sequence of the 20 amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"e3b4feb2-2d6a-42f4-b2b1-53de2d9a428e","url":"urn:test","contentType":"application/octet-stream","language":"en","databaseLabel":"","summary":"","weight":3.7249496,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["s-Graham’s Frog Oligopeptide-1"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["s-Graham’s Frog Oligopeptide-1 is a single chain peptide produced synthetically to be identical to a portion of the protein Immunoregulatory Peptide Odorregulin E1 which is found in the frog, Rana draytonii, and contains 11 amino acids which may contain disulfide bonds and/or glycosylation. The parent protein contains a maximum of 53 amino acids and consists of the proper sequence of the 20 amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["e3b4feb2-2d6a-42f4-b2b1-53de2d9a428e"],"reference":["0e11bef5-569a-4b48-ba88-b368ef774b78"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["S-GRAHAM’S FROG OLIGOP