  (106251, 'a27a0f05-416e-4490-bf6f-b8ea9f83560a'::uuid, 'R-HUMAN EMBRYONIC KIDNEY CELL 293 EXOSOMES/SH-(POLYPEPTIDE-3/POLYPEPTIDE-9/POLYPEPTIDE-189)', 'r-Human Embryonic Kidney Cell 293 Exosomes/sh-(Polypeptide-3/Polypeptide-9/Polypeptide-189)', NULL, NULL, NULL, 'r-Human Embryonic Kidney Cell 293 Exosomes/sh-(Polypeptide-3/Polypeptide-9/Polypeptide-189) are the exosomes released into and isolated from the growth media removed from cultures of recombinantly modified human embryonic kidney cells after several days of growth that contain sh-Polypeptide-3, sh-Polypeptide-9, and sh-Polypeptide-189. The starting media is Dulbecco''s Modified Eagle Medium, and may or may not contain fetal bovine serum.', NULL, NULL, 'II/416', '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"a27a0f05-416e-4490-bf6f-b8ea9f83560a","url":"urn:test","contentType":"application/octet-stream","language":"en","databaseLabel":"","summary":"","weight":5.3189683,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["r-Human Embryonic Kidney Cell 293 Exosomes/sh-(Polypeptide-3/Polypeptide-9/Polypeptide-189)"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["r-Human Embryonic Kidney Cell 293 Exosomes/sh-(Polypeptide-3/Polypeptide-9/Polypeptide-189) are the exosomes released into and isolated from the growth media removed from cultures of recombinantly modified human embryonic kidney cells after several days of growth that contain sh-Polypeptide-3, sh-Polypeptide-9, and sh-Polypeptide-189. The starting media is Dulbecco''s Modified Eagle Medium, and may or may not contain fetal bovine serum."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["a27a0f05-416e-4490-bf6f-b8ea9f83560a"],"reference":["a77cb3ac-79b3-40fe-b05d-b73515e20f40"],"cosmeticRestriction":["II/416"],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["R-HUMAN EMBRYONIC KIDNEY CELL 293 EXOSOMES/SH-(POLYPEPTIDE-3/POLYPEPTIDE-9/POLYPEPTIDE-189)"],"officialJournalPublication":["Y"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["106251"],"productTypeBodyParts":[],"annexNo":[],"phEurName":[],"es_ContentType":["application/octet-stream"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["SKIN CONDITIONING - HUMECTANT","SKIN CONDITIONING - MISCELLANEOUS"],"esDA_FirstIngestDate":["2026-06-25T09:34:04.222+0200"],"esDA_IngestDate":["2026-06-25T09:34:04.222+0200"],"currentVersion":[],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2026-06-25T09:34:04.201+0200"],"refNo_digit":[],"colour":[],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"a27a0f05-416e-4490-bf6f-b8ea9f83560a. Available at: urn:test"}'::jsonb),
  (106252, '34452f1a-8975-44d4-b7a4-02712c66e068'::uuid, 'S-MUSSEL (PENTAPEPTIDE-125 DI-HYDROXYPROLINE TRIPEPTIDE-138 LYSINE N6-(PENTAPEPTIDE-125 DI-HYDROXYPROLINE TRIPEPTIDE-138))', 's-Mussel (Pentapeptide-125 Di-Hydroxyproline Tripeptide-138 Lysine N6-(Pentapeptide-125 Di-Hydroxyproline Tripeptide-138))', NULL, NULL, NULL, 's-Mussel (Pentapeptide-125 Di-Hydroxyproline Tripeptide-138 Lysine N6-(Pentapeptide-125 Di-Hydroxyproline Tripeptide-138)) is a single chain peptide containing 21 amino acids consisting of Pentapeptide-125, two repeats of Hydroxyproline, and Tripeptide-138, modified at the N6 position of the Lysine by a peptide consisting of Pentapeptide-125, two repeats of Hydroxyproline, and Tripeptide-138. It is synthetically produced and inspired by sequence from Adhesive Plaque Matrix Protein which is found in the mussel, Mytilus edulis. Adhesive Plaque Matrix Protein contains 875 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"34452f1a-8975-44d4-b7a4-02712c66e068","url":"urn:test","contentType":"application/octet-stream","language":"en","databaseLabel":"","summary":"","weight":3.9449465,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["s-Mussel (Pentapeptide-125 Di-Hydroxyproline Tripeptide-138 Lysine N6-(Pentapeptide-125 Di-Hydroxyproline Tripeptide-138))"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["s-Mussel (Pentapeptide-125 Di-Hydroxyproline Tripeptide-138 Lysine N6-(Pentapeptide-125 Di-Hydroxyproline Tripeptide-138)) is a single chain peptide containing 21 amino acids consisting of Pentapeptide-125, two repeats of Hydroxyproline, and Tripeptide-138, modified at the N6 position of the Lysine by a peptide consisting of Pentapeptide-125, two repeats of Hydroxyproline, and Tripeptide-138. It is synthetically produced and inspired by sequence from Adhesive Plaque Matrix Protein which is found in the mussel, Mytilus edulis. Adhesive Plaque Matrix Protein contains 875 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["34452f1a-8975-44d4-b7a4-02712c66e068"],"reference":["d3ea3821-313f-428a-8500-3ee37bc85459"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["S-MUSSEL (PENTAPEPTIDE-125 DI-HYDROXYPROLINE TRIPEPTIDE-138 LYSINE N6-(PENTAPEPTIDE-125 DI-HYDROXYPROLINE TRIPEPTIDE-138))"],"officialJournalPublication":["Y"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["106252"],"productTypeBodyParts":[],"annexNo":[],"phEurName":[],"es_ContentType":["application/octet-stream"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["ANTIOXIDANT","SKIN PROTECTING"],"esDA_FirstIngestDate":["2026-06-25T16:21:00.940+0200"],"esDA_IngestDate":["2026-06-25T16:21:00.940+0200"],"currentVersion":[],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2026-06-25T16:21:00.922+0200"],"refNo_digit":[],"colour":[],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"34452f1a-8975-44d4-b7a4-02712c66e068. Available at: urn:test"}'::jsonb),
