  (106399, '531c0b27-b4bd-445c-9900-22480f1625ae'::uuid, 'OLIGOPEPTIDE-301', 'Oligopeptide-301', NULL, NULL, NULL, 'Oligopeptide-301 is the synthetic peptide containing 11 amino acids consisting of arginine, asparagine, glycine, lysine, methionine, phenylalanine, proline, tryptophan and valine.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"531c0b27-b4bd-445c-9900-22480f1625ae","url":"urn:test","contentType":"application/octet-stream","language":"en","databaseLabel":"","summary":"","weight":4.081362,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["Oligopeptide-301"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Oligopeptide-301 is the synthetic peptide containing 11 amino acids consisting of arginine, asparagine, glycine, lysine, methionine, phenylalanine, proline, tryptophan and valine."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["531c0b27-b4bd-445c-9900-22480f1625ae"],"reference":["096124e9-867e-4e68-971e-15b85b723fac"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["OLIGOPEPTIDE-301"],"officialJournalPublication":["Y"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["106399"],"productTypeBodyParts":[],"annexNo":[],"phEurName":[],"es_ContentType":["application/octet-stream"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["SKIN CONDITIONING - MISCELLANEOUS"],"esDA_FirstIngestDate":["2026-06-19T09:06:44.295+0200"],"esDA_IngestDate":["2026-06-19T09:06:44.295+0200"],"currentVersion":[],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2