  (106400, 'a7a90ad3-feec-46a8-9555-78df179d79a2'::uuid, 'SR-(METHIONYL TRIPEPTIDE-46 HEXAPEPTIDE-40 DECAPEPTIDE-27 SH-POLYPEPTIDE-190 SH-POLYPEPTIDE-191)', 'sr-(Methionyl Tripeptide-46 Hexapeptide-40 Decapeptide-27 sh-Polypeptide-190 sh-Polypeptide-191)', NULL, NULL, NULL, 'sr-(Methionyl Tripeptide-46 Hexapeptide-40 Decapeptide-27 sh-Polypeptide-190 sh-Polypeptide-191) is a single chain recombinant peptide produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the genes from Tripeptide-46, Hexapeptide-40, Decapeptide-27, sh-Polypeptide-190, and sh-Polypeptide-191 with the initiation code for methionine. The fusion peptide contains 353 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence from the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"a7a90ad3-feec-46a8-9555-78df179d79a2","url":"urn:test","contentType":"application/octet-stream","language":"en","databaseLabel":"","summary":"","weight":3.9449465,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["sr-(Methionyl Tripeptide-46 Hexapeptide-40 Decapeptide-27 sh-Polypeptide-190 sh-Polypeptide-191)"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sr-(Methionyl Tripeptide-46 Hexapeptide-40 Decapeptide-27 sh-Polypeptide-190 sh-Polypeptide-191) is a single chain recombinant peptide produced by fermentation in E. coli. The starting gene is synthesized by the fusion of the genes from Tripeptide-46, Hexapeptide-40, Decapeptide-27, sh-Polypeptide-190, and sh-Polypeptide-191 with the initiation code for methionine. The fusion peptide contains 353 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence from the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["a7a90ad3-feec-46a8-9555-78df179d79a2"],"reference":["e41d8a3b-ccd4-445b-8ebf-5ebd72641313"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["SR-(METHIONYL TRIPEPTIDE-46 HEXAPEPTIDE-40 DECAPEPTIDE-27 SH-POLYPEPTIDE-190 SH-POLYPEPTIDE-191)"],"officialJournalPublication":["Y"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["106400"],"productTypeBodyParts":[],"annexNo":[],"phEurName":[],"es_ContentType":["application/octet-stream"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["ANTIOXIDANT","REDUCING"],"esDA_FirstIngestDate":["2026-06-25T16:38:13.971+0200"],"esDA_IngestDate":["2026-06-25T16:38:13.971+0200"],"currentVersion":[],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2026-06-25T16:38:13.955+0200"],"refNo_digit":[],"colour":[],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"a7a90ad3-feec-46a8-9555-78df179d79a2. Available at: urn:test"}'::jsonb),
  (106401, '8154d96d-0a0c-477f-afb7-1fac5891fc69'::uuid, 'S-HONEYBEE OLIGOPEPTIDE-2 AMIDE TRIFLUOROACETATE', 's-Honeybee Oligopeptide-2 Amide Trifluoroacetate', NULL, NULL, NULL, 's-Honeybee Oligopeptide-2 Amide Trifluoroacetate is the trifluoroacetate salt of a peptide inspired by a sequence from Melittin which is found in the honey bee, Apis. The parent peptide contains 70 amino acids in which the C-terminus is an amide, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"8154d96d-0a0c-477f-afb7-1fac5891fc69","url":"urn:test","contentType":"application/octet-stream","language":"en","databaseLabel":"","summary":"","weight":4.081362,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["s-Honeybee Oligopeptide-2 Amide Trifluoroacetate"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["s-Honeybee Oligopeptide-2 Amide Trifluoroacetate is the trifluoroacetate salt of a peptide inspired by a sequence from Melittin which is found in the honey bee, Apis. The parent peptide contains 70 amino acids in which the C-terminus is an amide, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["8154d96d-0a0c-477f-afb7-1fac5891fc69"],"reference":["a152b998-5b49-49ba-aa6f-b8d21ecf017e"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["S-HONEYBEE OLIGOPEPTIDE-2 AMIDE TRIFLUOROACETATE"],"officialJournalPublication":["Y"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["106401"],"p