  (106402, '7d3a893b-60fe-40be-a737-9b3455545af7'::uuid, 'SH-OLIGOPEPTIDE-2 SP TRIFLUOROACETATE', 'sh-Oligopeptide-2 SP Trifluoroacetate', NULL, NULL, NULL, 'sh-Oligopeptide-2 SP Trifluoroacetate is the trifluoroacetate salt of a single chain human peptide produced synthetically to be identical to a portion of the protein, Erythropoietin and contains 19 amino acids consisting of alanine, arginine, aspartic acid, glycine, histidine, leucine, lysine, serine, threonine and valine. The parent peptide contains a maximum of 193 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"7d3a893b-60fe-40be-a737-9b3455545af7","url":"urn:test","contentType":"application/octet-stream","language":"en","databaseLabel":"","summary":"","weight":3.711493,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["sh-Oligopeptide-2 SP Trifluoroacetate"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Oligopeptide-2 SP Trifluoroacetate is the trifluoroacetate salt of a single chain human peptide produced synthetically to be identical to a portion of the protein, Erythropoietin and contains 19 amino acids consisting of alanine, arginine, aspartic acid, glycine, histidine, leucine, lysine, serine, threonine and valine. The parent peptide contains a maximum of 193 amino acids which may contain disulfide bonds and/or glycosylation. The protein consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["7d3a893b-60fe-40be-a737-9b3455545af7"],"reference":["128eec02-09f9-485c-9108-fb76c31b31eb"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["SH-OLIGOPEPTIDE-2 SP TRIFLUOROACETATE"],"officialJournalPublication":["Y"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["106402"],"productTypeBodyParts":[],"annexNo":[],"phEurName":[],"es_ContentType":["application/octet-stream"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["HAIR CONDITIONING","HUMECTANT","SKIN PROTECTING","SKIN CONDITIONING - MISCELLANEOUS"],"esDA_FirstIngestDate":["2026-06-25T15:10:07.023+0200"],"esDA_IngestDate":["2026-06-25T15:10:07.023+0200"],"currentVersion":[],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2026-06-25T15:10:07.001+0200"],"refNo_digit":[],"colour":[],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"7d3a893b-60fe-40be-a737-9b3455545af7. Available at: urn:test"}'::jsonb),
  (106403, 'bedfdb1b-7df5-46dc-ac07-bb9b471330de'::uuid, 'ESCHERICHIA COLI EXTRACT/SR-(ENTEROBACTERIA PHAGE T7 POLYPEPTIDE-1 PENTAPEPTIDE-70 POLY-SPIDER POLYPEPTIDE-1)', 'Escherichia Coli Extract/sr-(Enterobacteria Phage T7 Polypeptide-1 Pentapeptide-70 Poly-Spider Polypeptide-1)', NULL, NULL, NULL, 'Escherichia Coli Extract/sr-(Enterobacteria Phage T7 Polypeptide-1 Pentapeptide-70 Poly-Spider Polypeptide-1) is a single chain recombinant peptide produced by fermentation in E. coli, where the final product contains proteins from the E. coli host. The starting gene is synthesized by the fusion of the gene from sr-Enterobacteria Phage T7 Polypeptide-1, Pentapeptide-70, and 48 repeats of s-Spider Polypeptide-1. The fusion peptide contains 1696 amino acids which may contain disulfide bonds and/or glycosylation and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"bedfdb1b-7df5-46dc-ac07-bb9b471330de","url":"urn:test","contentType":"application/octet-stream","language":"en","databaseLabel":"","summary":"","weight":4.081362,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["Escherichia Coli Extract/sr-(Enterobacteria Phage T7 Polypeptide-1 Pentapeptide-70 Poly-Spider Polypeptide-1)"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Escherichia Coli Extract/sr-(Enterobacteria Phage T7 Polypeptide-1 Pentapeptide-70 Poly-Spider Polypeptide-1) is a single chain recombinant peptide produced by fermentation in E. coli, where the final product contains proteins from the E. coli host. The starting gene is synthesized by the fusion of the gene from sr-Enterobacteria Phage T7 Polypeptide-1, Pentapeptide-70, and 48 repeats of s-Spider Polypeptide-1. The fusion peptide contains 1696 amino acids which may contain disulfide bonds and/or glycosylation and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["bedfdb1b-7df5-46dc-ac07-bb9b471330de"],"reference":["2dd319cc-0de2-45a9-8224-ded6c87983a4"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["ESCHERICHIA COLI EXTRACT/SR-(ENTEROBACTERIA PHAGE T7 POLYPEPTIDE-1 PENTAPEPTIDE-70 POLY-SPIDER POLYPEPTIDE-1)"],"officialJournalPublication":["Y"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["106403"],"productTypeBodyParts":[],"annexNo":[],"phEurName":[],"es_ContentType":["application/octet-stream"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["SKIN CONDITIONING - MISCELLANEOUS"],"esDA_FirstIngestDate":["2026-06-04T11:07:17.719+0200"],"esDA_IngestDate":["2026-06-04T11:07:17.719+0200"],"currentVersion":[],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2026-06-04T11:07:17.695+0200"],"refNo_digit":[],"colour":[],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"bedfdb1b-7df5-46dc-ac07-bb9b471330de. Available at: urn:test"}'::jsonb),
  (106404, '92346b79-9acd-43e9-9e23-86ace7ed0d7c'::uuid, 'CAFFEOYL DIPEPTIDE-17 HYDROXYPROLINE', 'Caffeoyl Dipeptide-17 Hydroxyproline', NULL, NULL, NULL, 'Caffeoyl Dipeptide-17 Hydroxyproline is the product obtained by the reaction of Caffeic Acid and the synthetic peptide consisting of Dipeptide-17 and Hydroxyproline.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"92346b79-9acd-43e9-9e23-86ace7ed0d7c","url":"urn:test","contentType":"application/octet-stream","language":"en","databaseLabel":"","summary":"","weight":3.9449465,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["Caffeoyl Dipeptide-17 Hydroxyproline"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Caffeoyl Dipeptide-17 Hydroxyproline is the product obtained by the reaction of Caffeic Acid and the synthetic peptide consisting of Dipeptide-17 and Hydroxyproline."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["92346b79-9acd-43e9-9e23-86ace7ed0d7c"],"reference":["33695f5a-4e48-4df2-bc53-0667c183a930"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["CAFFEOYL DIPEPTIDE-17 HYDROXYPROLINE"],"officialJournalPublication":["Y"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["106404"],"productTypeBodyParts":[],"annexNo":[],"phEurName":[],"es_ContentType":["application/octet-stream"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["ANTIOXIDANT","HAIR CONDITIONING","SKIN PROTECTING","SKIN CONDITIONING - MISCELLANEOUS"],"esDA_FirstIngestDate":["2026-05-22T15:38:15.162+0200"],"esDA_IngestDate":["2026-05-2