  (106726, '22ed67af-5696-4c2f-83b1-e4eac348142b'::uuid, 'SH-OCTAPEPTIDE-28 SP', 'sh-Octapeptide-28 SP', NULL, NULL, NULL, 'sh-Octapeptide-28 SP is a single chain human peptide, produced synthetically to be identical to a portion of the protein, Alpha-Melanocyte-Stimulating Hormone, and consists of arginine, glycine, histidine, methionine, phenylalanine, tryptophan, tyrosine and valine. The parent protein contains a maximum of 26 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"22ed67af-5696-4c2f-83b1-e4eac348142b","url":"urn:test","contentType":"application/octet-stream","language":"en","databaseLabel":"","summary":"","weight":3.9449465,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["sh-Octapeptide-28 SP"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Octapeptide-28 SP is a single chain human peptide, produced synthetically to be identical to a portion of the protein, Alpha-Melanocyte-Stimulating Hormone, and consists of arginine, glycine, histidine, methionine, phenylalanine, tryptophan, tyrosine and valine. The parent protein contains a maximum of 26 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["22ed67af-5696-4c2f-83b1-e4eac348142b"],"reference":["463fafde-dbee-4b10-9716-7a4f870d135a"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIn