  (106757, '73f62924-6ad3-4174-8cc5-2de918634dcf'::uuid, 'SH-OLIGOPEPTIDE-205 SP AMIDE', 'sh-Oligopeptide-205 SP Amide', NULL, NULL, NULL, 'sh-Oligopeptide-205 SP Amide is a single chain human peptide produced synthetically to be identical to a portion of the protein, Natriuretic Peptides A, and contains 17 amino acids consisting of alanine, arginine, aspartic acid, cysteine, glutamine, glycine, isoleucine, leucine, methionine, phenylalanine and serine, in which the C-terminus is an amide. The parent protein contains a maximum of 151 amino acids which may contain disulfide bonds and/or glycosylation and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"73f62924-6ad3-4174-8cc5-2de918634dcf","url":"urn:test","contentType":"application/octet-stream","language":"en","databaseLabel":"","summary":"","weight":4.081362,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["sh-Oligopeptide-205 SP Amide"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["sh-Oligopeptide-205 SP Amide is a single chain human peptide produced synthetically to be identical to a portion of the protein, Natriuretic Peptides A, and contains 17 amino acids consisting of alanine, arginine, aspartic acid, cysteine, glutamine, glycine, isoleucine, leucine, methionine, phenylalanine and serine, in which the C-terminus is an amide. The parent protein contains a maximum of 151 amino acids which may contain disulfide bonds and/or glycosylation and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["73f62924-6ad3-4174-8cc5-2de918634dcf"],"reference":["273a13d6-9c18-46bb-88c4-3fb22982bcc2"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["SH-OLIGOPEPTIDE-205 SP AMIDE"],"officialJournalPublication":["Y"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["106757"],"productTypeBodyParts":[],"annexNo":[],"phEurName":[],"es_ContentType":["application/octet-stream"],"otherRegulations":[],"classificationInformation":["[]"],"functionName":["SKIN PROTECTING","SKIN CONDITIONING - MISCELLANEOUS"],"esDA_FirstIngestDate":["2026-06-25T11:09:25.258+0200"],"esDA_IngestDate":["2026-06-25T11:09:25.258+0200"],"currentVersion":[],"url":["urn:test"],"esST_URL":["urn:test"],"esDA_QueueDate":["2026-06-25T11:09:25.239+0200"],"refNo_digit":[],"colour":[],"wordingOfConditions":[],"inciUsaName":[],"relatedRegulations":[],"perfuming":["N"],"status":["Active"]},"enrichedMetadata":{},"children":[],"highlightedFragments":[],"citation":"73f62924-6ad3-4174-8cc5-2de918634dcf. Available at: urn:test"}'::jsonb),
  (106758, '11bc0ab2-e7e1-4fe1-a19a-8263293f5906'::uuid, 'S-CHLORELLA SOROKIANIANA PENTAPEPTIDE-1', 's-Chlorella Sorokianiana Pentapeptide-1', NULL, NULL, NULL, 's-Chlorella Sorokianiana Pentapeptide-1 is a single chain synthetic peptide produced to be identical to the gene which codes for tRNA (Guanine(37)-N1)-Methyltransferase found in Chlorella sorokianiana. The parent protein contains a maximum of 1946 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"11bc0ab2-e7e1-4fe1-a19a-8263293f5906","url":"urn:test","contentType":"application/octet-stream","language":"en","databaseLabel":"","summary":"","weight":4.081362,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["s-Chlorella Sorokianiana Pentapeptide-1"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["s-Chlorella Sorokianiana Pentapeptide-1 is a single chain synthetic peptide produced to be identical to the gene which codes for tRNA (Guanine(37)-N1)-Methyltransferase found in Chlorella sorokianiana. The parent protein contains a maximum of 1946 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["11bc0ab2-e7e1-4fe1-a19a-8263293f5906"],"reference":["84950656-7adb-4928-8e48-7f44840551fc"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["S-CHLORELLA SOROKIANIANA PENTAPEPTIDE-1"],