  (106830, '49c78a95-841c-4226-ab6f-0028bb670092'::uuid, 'S-SNAIL OLIGOPEPTIDE-2', 's-Snail Oligopeptide-2', NULL, NULL, NULL, 's-Snail Oligopeptide-2 is a single chain protein synthetically produced based on a sequence from Pro-Neuropeptide Y-Like Protein which is found in the snail, and contains 18 amino acids. The parent protein contains a maximum of 81 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"49c78a95-841c-4226-ab6f-0028bb670092","url":"urn:test","contentType":"application/octet-stream","language":"en","databaseLabel":"","summary":"","weight":3.7249496,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["s-Snail Oligopeptide-2"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["s-Snail Oligopeptide-2 is a single chain protein synthetically produced based on a sequence from Pro-Neuropeptide Y-Like Protein which is found in the snail, and contains 18 amino acids. The parent protein contains a maximum of 81 amino acids which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["49c78a95-841c-4226-ab6f-0028bb670092"],"reference":["046b6d4b-79aa-4090-b401-5c91bc5cc39e"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["S-SNAIL OLIGOPEPTIDE-2"],"officialJournalPublication":["Y"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["106830"],"productTypeBodyPar