  (106834, '23d58b56-b495-4030-88ec-453dce6ff5f4'::uuid, 'S-BEE OLIGOPEPTIDE-1', 's-Bee Oligopeptide-1', NULL, NULL, NULL, 's-Bee Oligopeptide-1 is a single chain synthetic peptide inspired by a sequence from FUN Polypeptide which is found in the cloudy masked bee, Hylaeus nubilosus. The parent protein is a very large (~5451 aa) peptide which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids.', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"23d58b56-b495-4030-88ec-453dce6ff5f4","url":"urn:test","contentType":"application/octet-stream","language":"en","databaseLabel":"","summary":"","weight":4.081362,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["s-Bee Oligopeptide-1"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["s-Bee Oligopeptide-1 is a single chain synthetic peptide inspired by a sequence from FUN Polypeptide which is found in the cloudy masked bee, Hylaeus nubilosus. The parent protein is a very large (~5451 aa) peptide which may contain disulfide bonds and/or glycosylation, and consists of the proper sequence of the 20 standard amino acids."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["23d58b56-b495-4030-88ec-453dce6ff5f4"],"reference":["8431dad5-c4fb-40c8-be95-b1a01af10a4b"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["S-BEE OLIGOPEPTIDE-1"],"officialJournalPublication":["Y"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["106834"],"productTypeBodyParts":[],"annexNo":[],"phEurName":[],"es_ContentT