  (107013, '25ef27f2-fcca-43dc-9288-9a9d66891b7f'::uuid, 'IRRADIATED HUMAN IMMORTAL KERATINOCYTE EXOSOMES', 'Irradiated Human Immortal Keratinocyte Exosomes', NULL, NULL, NULL, 'UV-Irradiated Human Immortal Keratinocyte Exosomes are the exosomes secreted by irradiated and immortalized human keratinocytes into the media after several days of growth. The cells are immortalized spontaneously and irradiated with UVB light. The starting media is a serum-free nutrient media.', NULL, NULL, 'II/416', '[]', NULL, NULL, 'Active', FALSE, TRUE, NULL, NULL, NULL, '{"apiVersion":"2.151","reference":"25ef27f2-fcca-43dc-9288-9a9d66891b7f","url":"urn:test","contentType":"application/octet-stream","language":"en","databaseLabel":"","summary":"","weight":3.711493,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["Irradiated Human Immortal Keratinocyte Exosomes"],"refNo":[],"otherRestrictions":[],"note":[],"sccsOpinionUrls":[],"itemType":["ingredient"],"other":[],"innName":[],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["UV-Irradiated Human Immortal Keratinocyte Exosomes are the exosomes secreted by irradiated and immortalized human keratinocytes into the media after several days of growth. The cells are immortalized spontaneously and irradiated with UVB light. The starting media is a serum-free nutrient media."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"esST_REFERENCE":["25ef27f2-fcca-43dc-9288-9a9d66891b7f"],"reference":["4ec3cde9-e9de-4693-b938-1db6d739376d"],"cosmeticRestriction":["II/416"],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"inciName":["IRRADIATED HUMAN IMMORTAL KERATINOCYTE EXOSOMES"],"officialJournalPublication":["Y"],"esST_FileName":["file.txt"],"casNo":[],"substanceId":["107013"],"productTypeBodyParts":[],"annex