  (35851, '877337a9-4a8b-4d17-bed7-f3a39d335e80'::uuid, 'PARFUM', 'PARFUM', NULL, 'Parfum', NULL, 'Parfum is a term for ingredient labelling used to identify that a product contains a material or a combination of materials normally added to a cosmetic to produce or to mask a particular odour. According to Article 19 of the Cosmetics Regulation, ''Perfume and aromatic compositions and their raw materials shall be referred  to  by  the  terms  ‘parfum’  or  ‘aroma’. ''', NULL, NULL, NULL, '[]', NULL, NULL, 'Active', FALSE, TRUE, 1, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"877337a9-4a8b-4d17-bed7-f3a39d335e80","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":4.8836107,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["PARFUM"],"otherRestrictions":["ban substances that deplete the ozone layer"],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["Parfum is a term for ingredient labelling used to identify that a product contains a material or a combination of materials normally added to a cosmetic to produce or to mask a particular odour. According to Article 19 of the Cosmetics Regulation, ''Perfume and aromatic compositions and their raw materials shall be referred  to  by  the  terms  ‘parfum’  or  ‘aroma’. ''"],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["DA94CCF18C630CDB442E76A9810E22EA"],"cosmeticRestriction":[],"ecNo":[],"maximumConcentration":[],"identifiedIngredient":[],"officialJournalPublication":["Y"],"inciName":["PARFUM"],"esST_FileName":["file.txt"],