  (41328, '6166f166-7a24-446d-b5a3-c7eb8d60fb7f'::uuid, 'ABIES SIBIRICA NEEDLE OIL', 'ABIES SIBIRICA NEEDLE OIL', NULL, NULL, NULL, '"Siberian Fir Needle Oil". Abies Sibirica needle Oil is an essential oil distilled from the needles and branches of the fir, Abies sibirica, Pinaceeae. It contains about 40% esters calculated as bornyl acetate, pinene, camphene, DL-limonene, and phellandrene.', NULL, '294-351-9', 'III/106', '[]', NULL, NULL, 'Active', TRUE, FALSE, 1, 'GROWTH_COSING', 'Growth Cosmetic Ingredients and Substances', '{"apiVersion":"2.151","reference":"6166f166-7a24-446d-b5a3-c7eb8d60fb7f","url":"urn:test","contentType":"text/plain","language":"en","databaseLabel":"Growth Cosmetic Ingredients and Substances","database":"GROWTH_COSING","summary":"","weight":4.158987,"content":"","accessRestriction":false,"checksum":"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","metadata":{"nameOfCommonIngredientsGlossary":["ABIES SIBIRICA NEEDLE OIL"],"otherRestrictions":["ban substances that deplete the ozone layer","ban substances that deplete the ozone layer"],"note":[],"refNo":[],"sccsOpinionUrls":[],"innName":[],"other":[],"itemType":["ingredient"],"chemicalName":[],"sccsOpinion":[],"esST_DATASOURCE":["GROWTH_COSING"],"refNo_letter":[],"language":["en"],"chemicalDescription":["\"Siberian Fir Needle Oil\". Abies Sibirica needle Oil is an essential oil distilled from the needles and branches of the fir, Abies sibirica, Pinaceeae. It contains about 40% esters calculated as bornyl acetate, pinene, camphene, DL-limonene, and phellandrene."],"esST_checksum":["E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"],"reference":["EF7FF5FC0281CD2C472FDFB0CBF15B23"],"cosmeticRestriction":["III/106"],"ecNo":["294-351-9"],"maximumConcentration":[],"identifiedIngredient":["87724"],"officialJournalPublication":["N"],"inciName":["ABIES SIBIRICA NEEDLE OIL"],"esST_FileName":["file.txt"],"casNo":["91697-89-1"],"substanceId":["41328"],"annexNo":[],"product